    using Point_2 = Kernel::Point_2;
    using Polygon_2 = std::vector<Point_2>;
    using Polygon_with_holes_2 = CGAL::Polygon_with_holes_2<Kernel>;
    using Polygon_set_2 = CGAL::Polygon_set_2<Kernel>;

    // Convert input polygons to CGAL format
    auto convert_to_cgal = [](const Polygon2d& poly) {
        Polygon_2 cgal_poly;
        for (const auto& point : poly.outer_boundary()) {
            cgal_poly.emplace_back(point.x(), point.y());
        }
        return cgal_poly;
    };

    Polygon_2 cgal_p1 = convert_to_cgal(P1);
    Polygon_2 cgal_p2 = convert_to_cgal(P2);

    // Create polygon set and compute intersection
    Polygon_set_2 ps1(cgal_p1);
    Polygon_set_2 ps2(cgal_p2);
    ps1.intersection(ps2);

    // Convert result back to output format
    std::vector<PolygonWithHoles2d> result;
    std::vector<Polygon_with_holes_2> cgal_result;
    ps1.polygons_with_holes(std::back_inserter(cgal_result));

    for (const auto& cgal_poly_with_holes : cgal_result) {
        PolygonWithHoles2d poly_with_holes;

        // Convert outer boundary
        Polygon2d outer;
        for (const auto& point : cgal_poly_with_holes.outer_boundary()) {
            outer.add_point(Point2d(CGAL::to_double(point.x()), CGAL::to_double(point.y())));
        }
        poly_with_holes.set_outer_boundary(outer);

        // Convert holes
        for (auto hole_it = cgal_poly_with_holes.holes_begin();
             hole_it != cgal_poly_with_holes.holes_end(); ++hole_it) {
            Polygon2d hole;
            for (const auto& point : *hole_it) {
                hole.add_point(Point2d(CGAL::to_double(point.x()), CGAL::to_double(point.y())));
            }
            poly_with_holes.add_hole(hole);
        }

        result.push_back(poly_with_holes);
    }

    return result;
    // END_CODE

